1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"reflect"
8		"sort"
9		"strconv"
10		"strings"
11		"testing"
12	)
13	
14	// 本文件在命令行端到端层面回归保障 ingest 的分段送达（packetization）
15	// 无关性：同一份标准输入，无论 Read 按什么大小返回数据，片段的结束位置
16	// 都不能被当成一行结束，每个非空白输入行只按原顺序产生一条完整的 JSON
17	// 结果；写入数量（added）、重复数量（duplicates）、查询统计（count/average）
18	// 以及最终退出状态都必须与整份一次到达时完全一致，空白行仍只占原始行号。
19	//
20	// 测试借助一个按指定边界把输入切成大小不一的片段逐段送达的 io.Reader，
21	// 在同一个输入脚本上遍历多种分段方式（含单字节与对齐 64 KiB 读缓冲的
22	// 边界），并直接构造原始字节，把多字节字符、JSON 转义以及代理项对的
23	// 字节精确放到片段边界上。
24	
25	// segmentedReader 按绝对字节偏移 cuts 把 data 分成若干片段，逐段 Read：
26	// 每个片段在一次 Read 中完整返回，片段之间没有其他字节。例如
27	// cuts={3,7} 时依次返回 data[:3]、data[3:7]、data[7:]。cuts 必须落在
28	// (0, len(data)) 内，会排序去重；cuts 为空时整份数据一次返回。
29	type segmentedReader struct {
30		data []byte
31		pos  int
32		cuts []int
33		idx  int
34	}
35	
36	func newSegmentedReader(data []byte, cuts ...int) *segmentedReader {
37		kept := cuts[:0:0]
38		for _, c := range cuts {
39			if c > 0 && c < len(data) {
40				kept = append(kept, c)
41			}
42		}
43		sort.Ints(kept)
44		out := kept[:0:0]
45		for i, c := range kept {
46			if i == 0 || c != out[len(out)-1] {
47				out = append(out, c)
48			}
49		}
50		return &segmentedReader{data: data, cuts: out}
51	}
52	
53	func (r *segmentedReader) Read(p []byte) (int, error) {
54		if len(p) == 0 {
55			return 0, nil
56		}
57		if r.pos >= len(r.data) {
58			// 最后一段返回后，下一次调用才给出 EOF：
59			// 即使最后一段恰好填满 p，也不会丢失或提前结束。
60			return 0, io.EOF
61		}
62		for r.idx < len(r.cuts) && r.cuts[r.idx] <= r.pos {
63			r.idx++
64		}
65		end := len(r.data)
66		if r.idx < len(r.cuts) {
67			end = r.cuts[r.idx]
68			r.idx++
69		}
70		n := copy(p, r.data[r.pos:end])
71		r.pos += n
72		if r.pos < end {
73			// p 小于当前段（本测试不会发生：p 为 64 KiB，段不超过 64 KiB）：
74			// 保留边界在同一位置，下次继续返回本段剩余部分。
75			r.idx--
76		}
77		return n, nil
78	}
79	
80	// segmentEvery 把整份输入按固定大小逐段送达。
81	func segmentEvery(data []byte, size int) io.Reader {
82		if size <= 0 {
83			size = 1
84		}
85		var cuts []int
86		for p := size; p < len(data); p += size {
87			cuts = append(cuts, p)
88		}
89		return newSegmentedReader(data, cuts...)
90	}
91	
92	// segments1Byte 逐字节送达（最强分段情形：多字节字符与转义的每个字节
93	// 都可能单独到达）。
94	func segments1Byte(data []byte) io.Reader {
95		return segmentEvery(data, 1)
96	}
97	
98	// runIngestForSegmentation 以给定 reader 执行一次 ingest，返回退出码与
99	// 逐条结果（已解析的 JSON）；输出必须始终是一条结果占一行。
100	func runIngestForSegmentation(t *testing.T, in io.Reader) (int, []map[string]interface{}) {
101		t.Helper()
102		var out bytes.Buffer
103		code := runIngest(in, &out)
104		text := out.String()
105		if text != "" && !strings.HasSuffix(text, "\n") {
106			t.Fatalf("every result must end with newline, got %q", text)
107		}
108		var results []map[string]interface{}
109		for _, line := range strings.Split(strings.TrimRight(text, "\n"), "\n") {
110			results = append(results, decodeResultLine(t, line))
111		}
112		return code, results
113	}
114	
115	// baselineResults 以整份一次到达的方式跑出基准退出码与逐条结果。
116	func baselineResults(t *testing.T, data []byte) (int, []map[string]interface{}) {
117		t.Helper()
118		return runIngestForSegmentation(t, bytes.NewReader(data))
119	}
120	
121	// assertMatchesBaseline 断言某种分段送达与整份一次到达产生完全相同的
122	// 退出码与逐条结果。
123	func assertMatchesBaseline(t *testing.T, label string, in io.Reader, baseCode int, baseRes []map[string]interface{}) {
124		t.Helper()
125		code, res := runIngestForSegmentation(t, in)
126		if code != baseCode {
127			t.Fatalf("%s: exit code = %d, want %d (same as whole-input delivery)",
128				label, code, baseCode)
129		}
130		if len(res) != len(baseRes) {
131			t.Fatalf("%s: %d result lines, want %d", label, len(res), len(baseRes))
132		}
133		for i := range baseRes {
134			if !reflect.DeepEqual(res[i], baseRes[i]) {
135				t.Fatalf("%s: result %d = %s\nwant %s",
136					label, i, mustJSON(res[i]), mustJSON(baseRes[i]))
137			}
138		}
139	}
140	
141	func mustJSON(v interface{}) string {
142		b, err := json.Marshal(v)
143		if err != nil {
144			return "<marshal error>"
145		}
146		return string(b)
147	}
148	
149	// uescape 以 ASCII 文本返回一个 JSON Unicode 转义（如 uescape("D83D") -> `\uD83D`），
150	// 使含反斜杠的原始字节可以在源码里以纯 ASCII 构造、精确放到片段边界上。
151	func uescape(hex string) string {
152		return `\u` + hex
153	}
154	
155	// segmentationVariants 在同一份输入上生成一组有代表性的分段方式：
156	// 单字节、2/3/5/7/16/64/100 字节等大小不一的段，以及对齐和错开
157	// 64 KiB 读缓冲的段（不含整份基线，基线单独用 baselineResults 跑）。
158	func segmentationVariants(data []byte) []struct {
159		label string
160		in    io.Reader
161	} {
162		type variant struct {
163			label string
164			in    io.Reader
165		}
166		mk := func(label string, in io.Reader) variant { return variant{label, in} }
167		vs := []variant{
168			mk("1-byte", segments1Byte(data)),
169			mk("2-byte", segmentEvery(data, 2)),
170			mk("3-byte", segmentEvery(data, 3)),
171			mk("5-byte", segmentEvery(data, 5)),
172			mk("7-byte", segmentEvery(data, 7)),
173			mk("16-byte", segmentEvery(data, 16)),
174			mk("64-byte", segmentEvery(data, 64)),
175			mk("100-byte", segmentEvery(data, 100)),
176			mk("64KiB-aligned", segmentEvery(data, 64*1024)),
177			mk("64KiB-offset-by-1", io.MultiReader(
178				bytes.NewReader(data[:1]),
179				segmentEvery(data[1:], 64*1024),
180			)),
181		}
182		out := make([]struct {
183			label string
184			in    io.Reader
185		}, len(vs))
186		for i, v := range vs {
187			out[i] = struct {
188				label string
189				in    io.Reader
190			}{v.label, v.in}
191		}
192		return out
193	}
