		var m map[string]interface{}
		if err := json.Unmarshal([]byte(lines[i]), &m); err != nil {
			t.Fatalf("line %d: %v", i, err)
		}
		if int(m["line"].(float64)) != wantLine {
			t.Fatalf("output %d = %v, want input line %d", i, m, wantLine)
		}
	}
}

